{
  "schema_version": 1,
  "action": "set_policy",
  "policy": {
    "model": "ae",
    "window": 3,
    "threshold_q": "default",
    "persistence": 3
  },
  "intent_understood_as": "balanced_operation",
  "reason": "Balanced operation requires <=5 false alarms/hour. AE at default threshold (q0.995) with persistence 1 yields 24.34/h, exceeding the budget. Raising persistence to 3 cuts AE false alarms to ~7.7/h (per capability card), still above 5/h. No AE configuration meets the 5/h budget; this policy provides the closest feasible trade-off while respecting the operator's model choice."
}
